macro_rules! deps {
    () => {
        Note!();
    };
}

macro_rules! SectionKind {
    () => {
        deps!();
        # [doc = " The kind of a section."] # [derive (Debug , Clone , Copy , PartialEq , Eq , Hash)] # [non_exhaustive] pub enum SectionKind { # [doc = " The section kind is unknown."] Unknown , # [doc = " An executable code section."] # [doc = ""] # [doc = " Example ELF sections: `.text`"] # [doc = ""] # [doc = " Example Mach-O sections: `__TEXT/__text`"] Text , # [doc = " A data section."] # [doc = ""] # [doc = " Example ELF sections: `.data`"] # [doc = ""] # [doc = " Example Mach-O sections: `__DATA/__data`"] Data , # [doc = " A read only data section."] # [doc = ""] # [doc = " Example ELF sections: `.rodata`"] # [doc = ""] # [doc = " Example Mach-O sections: `__TEXT/__const`, `__DATA/__const`, `__TEXT/__literal4`"] ReadOnlyData , # [doc = " A read only data section with relocations."] # [doc = ""] # [doc = " This is the same as either `Data` or `ReadOnlyData`, depending on the file format."] # [doc = " This value is only used in the API for writing files. It is never returned when reading files."] ReadOnlyDataWithRel , # [doc = " A loadable string section."] # [doc = ""] # [doc = " Example ELF sections: `.rodata.str`"] # [doc = ""] # [doc = " Example Mach-O sections: `__TEXT/__cstring`"] ReadOnlyString , # [doc = " An uninitialized data section."] # [doc = ""] # [doc = " Example ELF sections: `.bss`"] # [doc = ""] # [doc = " Example Mach-O sections: `__DATA/__bss`"] UninitializedData , # [doc = " An uninitialized common data section."] # [doc = ""] # [doc = " Example Mach-O sections: `__DATA/__common`"] Common , # [doc = " A TLS data section."] # [doc = ""] # [doc = " Example ELF sections: `.tdata`"] # [doc = ""] # [doc = " Example Mach-O sections: `__DATA/__thread_data`"] Tls , # [doc = " An uninitialized TLS data section."] # [doc = ""] # [doc = " Example ELF sections: `.tbss`"] # [doc = ""] # [doc = " Example Mach-O sections: `__DATA/__thread_bss`"] UninitializedTls , # [doc = " A TLS variables section."] # [doc = ""] # [doc = " This contains TLS variable structures, rather than the variable initializers."] # [doc = ""] # [doc = " Example Mach-O sections: `__DATA/__thread_vars`"] TlsVariables , # [doc = " A non-loadable string section."] # [doc = ""] # [doc = " Example ELF sections: `.comment`, `.debug_str`"] OtherString , # [doc = " Some other non-loadable section."] # [doc = ""] # [doc = " Example ELF sections: `.debug_info`"] Other , # [doc = " Debug information."] # [doc = ""] # [doc = " Example Mach-O sections: `__DWARF/__debug_info`"] Debug , # [doc = " Debug strings."] # [doc = ""] # [doc = " This is the same as either `Debug` or `OtherString`, depending on the file format."] # [doc = " This value is only used in the API for writing files. It is never returned when reading files."] DebugString , # [doc = " Information for the linker."] # [doc = ""] # [doc = " Example COFF sections: `.drectve`"] Linker , # [doc = " ELF note section."] Note , # [doc = " Metadata such as symbols or relocations."] # [doc = ""] # [doc = " Example ELF sections: `.symtab`, `.strtab`, `.group`"] Metadata , # [doc = " Some other ELF section type."] # [doc = ""] # [doc = " This is the `sh_type` field in the section header."] # [doc = " The meaning may be dependent on the architecture."] Elf (u32) , }
    };
}

SectionKind!()